if (cell >= cells_[stage]) return false;
if (owner_[stage][cell] != -1) return false;
if (parent_stage >= 0 && stage >= parent_stage) return false;

const std::bitset<256>& row = d_->banks[stage][cell / 2];
int half = static_cast<int>(cell % 2);
if (bulk_slot && half != 0) return false;
int rec = bulk_slot ? 0 : half * 128;

uint64_t type = field(row, rec, 3);
if (type < 1 || type > 5) return false;
bool half_size = (type == 1 || type == 4);
if (bulk_slot && half_size) {
    // a logically half size bulk root keeps its upper half zero padded
    for (int i = 128; i < 256; ++i)
        if (row[i]) return false;
}
uint32_t slot = bulk_slot ? 2 : (half_size ? 1 : 2);
if (!half_size && half != 0) return false;
if (cell + slot > cells_[stage]) return false;
if (G > forest_max_len(origin)) return false;

VNode node;
node.type = static_cast<int>(type);
node.origin = origin;
node.G = G;
node.reg_hi = reg_hi;
node.reg_lo = reg_lo;
node.stage = stage;
node.cell = cell;
node.parent = parent;
node.bulk_slot = bulk_slot;
node.bmp = static_cast<uint32_t>(field(row, rec + 3, 22));
node.bulk_stage = bulk_stage;

