if (type == 1 || type == 2 || type == 3) {
    bitmap_id = static_cast<int>(field(row, rec + 25, 16));
    ni_base = static_cast<uint32_t>(field(row, rec + 41, 22));
    if (bitmap_id < 0 || static_cast<size_t>(bitmap_id) >= d_->bitmaps.size()) return false;
    pattern = d_->bitmaps[bitmap_id];
    if (pattern & 1ULL) return false;  // bit 0 is unused
    uint64_t count = 0;
    for (int i = 1; i < 64; ++i)
        if ((pattern >> i) & 1ULL) count++;
    if (ni_base + count > d_->nexthops.size()) return false;
    if (count == 0 && ni_base != 0) return false;
    node.bitmap_id = bitmap_id;
